package am.ik.yavi.core;

import org.junit.jupiter.api.Test;
import java.util.Locale;
import static org.assertj.core.api.Assertions.assertThat;
import am.ik.yavi.builder.ValidatorBuilder;

public class ValidatorTest {

    // Define the User class
    public static class User {
        private String name;
        private String email;
        private int age;
        private boolean enabled;

        public User(String name, String email, int age, boolean enabled) {
            this.name = name;
            this.email = email;
            this.age = age;
            this.enabled = enabled;
        }

        public String getName() { return name; }
        public String getEmail() { return email; }
        public int getAge() { return age; }
        public boolean isEnabled() { return enabled; }
    }

    @Test
    void validateUserWithInvalidData() {
        // Arrange
        User user = new User("", "invalid-email", 300, false);
        Validator<User> validator = ValidatorBuilder.<User>of()
            .constraint(User::getName, "name", c -> c.notNull()
                .greaterThanOrEqual(1)
                .lessThanOrEqual(50))
            .constraint(User::getEmail, "email", c -> c.notNull()
                .email())
            .constraint(User::getAge, "age", c -> c.notNull()
                .lessThanOrEqual(150))
            .constraint(User::isEnabled, "enabled", c -> c.isTrue())
            .build();

        // Act
        ConstraintViolations violations = validator.validate(user, Locale.getDefault());

        // Assert
        assertThat(violations.isValid()).isFalse();
        assertThat(violations.details()).hasSize(4);
        assertThat(violations.details().get(0).getDefaultMessage())
            .isEqualTo("The size of \"name\" must be greater than or equal to 1. The given size is 0");
        assertThat(violations.details().get(1).getDefaultMessage())
            .isEqualTo("\"email\" must be a valid email address");
        assertThat(violations.details().get(2).getDefaultMessage())
            .isEqualTo("The age must be less than or equal to 150. The given value is 300");
        assertThat(violations.details().get(3).getDefaultMessage())
            .isEqualTo("The value must be true.");
    }
}

