    static class Validator<T> {
        private Set<Character> restrictedChars;
        private String messageKey;

        public Validator(Set<Character> restrictedChars, String messageKey) {
            this.restrictedChars = restrictedChars;
            this.messageKey = messageKey;
        }

        public ConstraintViolations validate(T target, Locale locale, ConstraintContext context) {
            ConstraintViolations violations = new ConstraintViolations();
            if (target instanceof User) {
                String name = ((User) target).getName();
                Set<Character> invalidChars = new LinkedHashSet<>();
                for (char c : name.toCharArray()) {
                    if (restrictedChars.contains(c)) {
                        invalidChars.add(c);
                    }
                }
                if (!invalidChars.isEmpty()) {
                    StringBuilder sb = new StringBuilder();
                    sb.append("[");
                    String joined = String.join(", ", invalidChars.stream()
                            .map(String::valueOf)
                            .toArray(String[]::new));
                    sb.append(joined);
                    sb.append("]");
                    violations.add(new ConstraintViolation(
                        "name",
                        messageKey,
                        "\"" + sb.toString() + "\" is/are not allowed for \"name\"",
                        null,
                        null,
                        locale
                    ));
                }
            }
            return violations;
        }
    }

    // Define ConstraintViolations and ConstraintViolation for demonstration purposes
    static class ConstraintViolations {
        private final Set<ConstraintViolation> violations = new LinkedHashSet<>();

        public void add(ConstraintViolation violation) {
            violations.add(violation);
        }

        public boolean isValid() {
            return violations.isEmpty();
        }

        public int size() {
            return violations.size();
        }

        public ConstraintViolation get(int index) {
            return violations.stream().skip(index).findFirst().orElse(null);
        }
    }

    static class ConstraintViolation {
        private final String name;
        private final String messageKey;
        private final String message;
        private final Object[] args;
        private final Object formatter;
        private final Locale locale;

        public ConstraintViolation(String name, String messageKey, String message, Object[] args, Object formatter, Locale locale) {
            this.name = name;
            this.messageKey = messageKey;
            this.message = message;
            this.args = args;
            this.formatter = formatter;
            this.locale = locale;
        }

        public String getMessage() {
            return message;
        }

        public String getMessageKey() {
            return messageKey;
        }
    }

    // Define a dummy ConstraintContext for demonstration purposes
    static class ConstraintContext {}

    @Test
    void validateNameWithInvalidCharacters() {
        // Create user with name containing invalid characters
        User user = new User("abcA@Bb.c");

        // Define restricted characters using LinkedHashSet to preserve order
        Set<Character> restrictedChars = new LinkedHashSet<>(Arrays.asList('A', 'B', 'a', 'b'));

        // Setup validator to check 'name' field against restricted characters
        Validator<User> validator = new Validator<>(restrictedChars, "codePoints.asBlackList");

        // Perform validation
        ConstraintViolations violations = validator.validate(user, Locale.getDefault(), new ConstraintContext());

        // Assertions
        assertThat(violations.isValid()).isFalse();
        assertThat(violations.size()).isEqualTo(1);
        assertThat(violations.get(0).getMessage())
            .isEqualTo("\"[A, B, a, b]\" is/are not allowed for \"name\"");
        assertThat(violations.get(0).getMessageKey()).isEqualTo("codePoints.asBlackList");
    }
