class ValidatorTest {

    @Test
    void codePointsAsBlackList() throws Exception {
        // 1. Create a set of forbidden Unicode characters including 'a' and 'b'
        CodePoints.CodePointsSet<String> blackList = () -> new HashSet<>(
            Arrays.asList(
                0x0061, // 'a'
                0x0062  // 'b'
            )
        );

        // 2. Create a user with the name "abcA@Bb.c"
        User user = new User("abcA@Bb.c", null, null);

        // 3. Set up a validator to check if the user's name contains any forbidden characters
        Validator<User> validator = ValidatorBuilder.of(User.class)
            .constraint(User::getName, "name",
                c -> c.codePoints(blackList).asBlackList())
            .build();

        // 4. Run the validation check on the user
        ConstraintViolations violations = validator.validate(user);

        // 1. The validation fails
        assertThat(violations.isValid()).isFalse();

        // 2. One error is reported
        assertThat(violations.size()).isEqualTo(1);

        // 3. The error message states that the characters 'a' and 'b' are not allowed in the name
        assertThat(violations.get(0).message())
            .isEqualTo("\"[a, b]\" is/are not allowed for \"name\"");

        // 4. The error has the identifier 'codePoints.asBlackList'
        assertThat(violations.get(0).messageKey()).isEqualTo("codePoints.asBlackList");
    }
}

