import am.ik.yavi.builder.ValidatorBuilder;

// Define the Group enum implementing ConstraintGroup
enum Group implements ConstraintGroup {
    UPDATE;

    @Override
    public String attribute(String name) {
        return name;
    }
}

// Define the User class
static class User {
    private final String name;
    private final String email;
    private final int age;

    public User(String name, String email, int age) {
        this.name = name;
        this.email = email;
        this.age = age;
    }

    public String getName() {
        return name;
    }

    public String getEmail() {
        return email;
    }

    public int getAge() {
        return age;
    }
}

public class ValidatorTest {

    @Test
    void validateValidatorWithGroup() {
        // Create a user instance with a name longer than 5 characters
        User user = new User("foobar", "foo@example.com", 30);

        // Build the validator with a constraint on the 'name' field's length when the update group is active
        Validator<User> validator = ValidatorBuilder.of(User.class)
            .constraintOnGroup(Group.UPDATE, b -> b.constraint(u -> u.getName(), "name", c -> c.maxLength(5)))
            .build();

        // Validate without specifying a group; should pass
        ConstraintViolations violations = validator.validate(user, Locale.ENGLISH);
        assertThat(violations.isValid()).isTrue();

        // Validate with the update group; should fail
        ConstraintViolations violationsWithGroup = validator.validate(user, Locale.ENGLISH, Group.UPDATE);
        assertThat(violationsWithGroup.isValid()).isFalse();
        assertThat(violationsWithGroup.size()).isEqualTo(1);
        assertThat(violationsWithGroup.get(0).message()).isEqualTo(
            "The size of \"name\" must be less than or equal to 5. The given size is 6");
        assertThat(violationsWithGroup.get(0).messageKey()).isEqualTo("container.maxLength");
    }
}

