        Validator<User> groupedValidator = ValidatorBuilder.of(User.class)
            .constraintOnGroup(updateGroup, b -> b
                .constraint(u -> u.getName(), "name", c -> c.lessThanOrEqual(5)))
            .constraintOnGroup(deleteGroup, b -> b
                .constraint(u -> u.getEmail(), "email", c -> c.email()))
            .build();

