import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;
import am.ik.yavi.builder.ValidatorBuilder;
import am.ik.yavi.core.ConstraintGroup;
import am.ik.yavi.core.ConstraintContext;
import java.util.Locale;

class ValidatorTest {

    // Define Group interface with UPDATE group extending ConstraintGroup
    interface Group {
        interface UPDATE extends ConstraintGroup {}
    }

    // Define User class with necessary fields and getters
    static class User {
        private final String name;
        private final String email;
        private final int age;

        User(String name, String email, int age) {
            this.name = name;
            this.email = email;
            this.age = age;
        }

        public String getName() {
            return name;
        }

        public String getEmail() {
            return email;
        }

        public int getAge() {
            return age;
        }
    }

    @Test
    void validateWithDefaultAndUpdateGroups() {
        User user = new User("foobar", "foo@example.com", -1);
        Validator<User> validator = ValidatorBuilder.of(User.class)
            .constraint(User::getEmail, "email", c -> c.maxLength(10))
            .constraintOnGroup(Group.UPDATE.class,
                b -> b.constraint(User::getName, "name", c -> c.maxLength(5)))
            .build();

        // Validate without specifying group
        ConstraintViolations violationsDefault = validator.validate(user, Locale.getDefault(), ConstraintContext.of(ConstraintGroup.DEFAULT));
        assertThat(violationsDefault.isValid()).isFalse();
        assertThat(violationsDefault.size()).isEqualTo(1);
        assertThat(violationsDefault.get(0).message()).isEqualTo(
            "The size of \"email\" must be less than or equal to 10. The given size is 16");

        // Validate with update group
        ConstraintContext updateContext = ConstraintContext.of(Group.UPDATE.class);
        ConstraintViolations violationsUpdate = validator.validate(user, Locale.getDefault(), updateContext);
        assertThat(violationsUpdate.isValid()).isFalse();
        assertThat(violationsUpdate.size()).isEqualTo(2);
        assertThat(violationsUpdate.get(0).message()).isEqualTo(
            "The size of \"email\" must be less than or equal to 10. The given size is 16");
        assertThat(violationsUpdate.get(1).message()).isEqualTo(
            "The size of \"name\" must be less than or equal to 5. The given size is 6");
    }
}

