import static org.assertj.core.api.Assertions.assertThat;

class ValidatorTest {

    @Test
    void calendarEntryBeforeFutureTimeValid() {
        // Set the current time to 12:30 PM
        LocalTime now = LocalTime.of(12, 30);
        CalendarEntryLocalTime calendarEntry = new CalendarEntryLocalTime("Meeting", now);

        // Configure validator to ensure the time is before 10:00 PM
        Validator<CalendarEntryLocalTime> validator = ValidatorBuilder
                .<CalendarEntryLocalTime>of()
                .constraint(CalendarEntryLocalTime::getTime, "time", c -> c.before(() -> LocalTime.of(22, 0)))
                .build();

        // Validate the calendar entry
        ConstraintViolations violations = validator.validate(calendarEntry);

        // Assert that the entry is valid and no violations are reported
        assertThat(violations.isValid()).isTrue();
        assertThat(violations.isEmpty()).isTrue();
    }

    // Define the CalendarEntryLocalTime class
    static class CalendarEntryLocalTime {
        private String name;
        private LocalTime time;

        public CalendarEntryLocalTime(String name, LocalTime time) {
            this.name = name;
            this.time = time;
        }

        public LocalTime getTime() {
            return time;
        }
    }
}

