    @Test
    void timeOnBoundaryShouldBeInvalid() {
        // Create a local time set to 12:30
        LocalTime boundaryTime = LocalTime.of(12, 30);

        // Create a calendar entry named 'Birthday Party' using the created local time
        CalendarEntryLocalTime birthdayPartyEntry = new CalendarEntryLocalTime("Birthday Party", boundaryTime);

        // Set up a validator that checks if the time falls between 12:30 and 12:30 (inclusive)
        Validator<CalendarEntryLocalTime> validator = ValidatorBuilder
                .<CalendarEntryLocalTime>of()
                .constraint(CalendarEntryLocalTime::getTime, "time", c -> c.between(() -> boundaryTime, () -> boundaryTime))
                .build();

        // Validate the calendar entry
        ConstraintViolations violations = validator.validate(birthdayPartyEntry, java.util.Locale.getDefault(), null);

        // Assert that validation fails
        assertThat(violations.isValid()).isFalse();

        // Assert that there is one constraint violation
        assertThat(violations.size()).isEqualTo(1);

        // Assert that the violation message states the time must be between 12:30 and 12:30
        String expectedMessage = "\"time\" has to be between 12:30 and 12:30";
        assertThat(violations.iterator().next().message()).isEqualTo(expectedMessage);
    }

}

