	public CharSequenceConstraint<T, E> uuid() {
		this.predicates().add(ConstraintPredicate.of(x -> {
			if (size().applyAsInt(x) == 0) {
				return true;
			}
			return VALID_UUID_REGEX.matcher(x).matches();
		}, CHAR_SEQUENCE_UUID, () -> new Object[] {}, VALID));
