	public CharSequenceConstraint<T, E> startsWith(CharSequence prefix) {
		this.predicates()
				.add(ConstraintPredicate.of(
						x -> x.toString().startsWith(prefix.toString()),
						CHAR_SEQUENCE_STARTSWITH, () -> new Object[] { prefix }, VALID));
