	public CharSequenceConstraint<T, E> pattern(Pattern regex) {
		this.predicates().add(ConstraintPredicate.of(x -> regex.matcher(x).matches(),
				CHAR_SEQUENCE_PATTERN, () -> new Object[] { regex.pattern() }, VALID));
