class CharSequenceConstraintTest {
    @Test
    void invalidUUID() {
        // Instantiate the constraint with appropriate type parameters
        CharSequenceConstraint<String, String> constraint = new CharSequenceConstraint<>();

        // Add the UUID predicate
        constraint.uuid();

        // Retrieve the last added predicate which should be the UUID validator
        ConstraintPredicate<String> predicate = constraint.predicates().getLast();

        String[] invalidUUIDs = {
