package am.ik.yavi.constraint;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Assertions;
import java.util.Arrays;
import java.util.List;
import java.util.function.Predicate;

class CharSequenceConstraintTest {

    @Test
    void invalidEndsWithDiego() {
        CharSequenceConstraint<String, String> constraint = new CharSequenceConstraint<>();
        constraint.endsWith("Diego");
        Predicate<String> predicate = constraint.predicates().peekFirst().predicate();

        List<String> testStrings = Arrays.asList(
            "HelloWorld",
            "GoodbyeEarth",
            "JavaProgramming",
            "ChatGPT",
            "OpenAI",
            "Dieg0",
            "Diegoo"
        );

        for (String testString : testStrings) {
            Assertions.assertFalse(predicate.test(testString), 
                "The string '" + testString + "' should not end with 'Diego'");
        }
    }
}

