import java.util.function.Predicate;

class CharSequenceConstraintTest {

    @Test
    void endsWithStringBuilderSuffix() {
        // Initialize StringBuilder with "Diego" and append "1"
        StringBuilder suffixBuilder = new StringBuilder("Diego");
        suffixBuilder.append("1");
        CharSequence suffix = suffixBuilder.toString();

        // Initialize CharSequenceConstraint with endsWith condition
        CharSequenceConstraint<String, String> constraint = new CharSequenceConstraint<>();
        constraint.endsWith(suffix);

        // Retrieve the predicate
        Predicate<String> predicate = constraint.predicates().peekFirst().predicate();

        // List of test strings that do not end with "Diego1"
        List<String> testStrings = Arrays.asList(
            "HelloWorld",
            "Goodbye",
            "Diego2",
            "Diega1",
            "Diego",
            "Diego12"
        );

        // Assert that predicate.test returns false for all test strings
        for (String testString : testStrings) {
            assertThat(predicate.test(testString)).isFalse();
        }
    }
}

