package ik.yavi.constraint;

import java.time.Instant;
import java.util.Deque;
import java.util.LinkedList;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.function.Supplier;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThatThrownBy;

class InstantConstraintTest {

    @Test
    void betweenWithInvalidRangeThrowsException() {
        Instant now = Instant.now();
        Instant start = now.plusSeconds(1);
        Instant end = now.minusSeconds(1);
        Predicate<Instant> predicate = retrievePredicate(
                c -> c.between(() -> start, () -> end));
        assertThatThrownBy(() -> predicate.test(now))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("start of the range must be before the end");
    }

    private static Predicate<Instant> retrievePredicate(
            Function<CustomInstantConstraint<Instant>, CustomInstantConstraint<Instant>> constraint) {
        return constraint.apply(new CustomInstantConstraint<>()).predicates().peekFirst()
                .predicate();
    }

    static class CustomInstantConstraint<T> {
        private final Deque<PredicateHolder<T>> predicates = new LinkedList<>();

        public CustomInstantConstraint<T> between(Supplier<Instant> startSupplier, Supplier<Instant> endSupplier) {
            predicates.addFirst(new PredicateHolder<>((T value) -> {
                if (!(value instanceof Instant)) {
                    throw new IllegalArgumentException("Value must be an Instant");
                }
                Instant instant = (Instant) value;
                Instant start = startSupplier.get();
                Instant end = endSupplier.get();
                if (start.isAfter(end)) {
                    throw new IllegalArgumentException("start of the range must be before the end");
                }
                return instant.isAfter(start) && instant.isBefore(end);
            }));
            return this;
        }

        public Deque<PredicateHolder<T>> predicates() {
            return predicates;
        }
    }

    static class PredicateHolder<T> {
        private final Predicate<T> predicate;

        public PredicateHolder(Predicate<T> predicate) {
            this.predicate = predicate;
        }

        public Predicate<T> predicate() {
            return predicate;
        }
    }
}

