    void isBeforeIdentifiesCurrentTimeAsPresentOrFuture() {
        Clock fixedClock = Clock.fixed(Instant.parse("2023-10-01T12:30:00Z"), ZoneId.systemDefault());
        LocalTimeConstraint<LocalTime> constraint = new LocalTimeConstraint<>();
        Predicate<LocalTime> predicate = time -> constraint.isBefore(time, BASE_TIME);

        LocalTime currentTime = LocalTime.now(fixedClock);
        assertThat(predicate.test(currentTime)).isFalse();

        LocalTime futureTime = currentTime.plus(1, ChronoUnit.HOURS);
        assertThat(predicate.test(futureTime)).isFalse();

        LocalTime pastTime = currentTime.minus(1, ChronoUnit.HOURS);
        assertThat(predicate.test(pastTime)).isTrue();
    }

}

