import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

class EmojiTest {

    @Test
    void testBestEffortCountWithComplexEmojis() {
        // Test string with length 46 and six distinct emojis
        String testString = "😀😃😄😁😆😅This is a test string with emojis.";
        int length = Emoji.bestEffortCount(testString);

        // Assert the length of the string
        assertThat(testString.length()).isEqualTo(46);

        // Assert the number of distinct emojis
        assertThat(length).isEqualTo(46);
    }
}

