class ByteSizeConstraintTest {
    @Test
    void greaterThanOrEqual() {
        // Arrange
        Charset charset = Charset.forName("UTF-8");
        ByteSizeConstraint<String, String> byteSizeConstraint =
                new ByteSizeConstraint<>(new CharSequenceConstraint<String, String>(), charset)
                        .greaterThanOrEqual(4);

        // Setup predicates list
        List<ConstraintPredicate<String, ?>> predicatesList = new ArrayList<>(byteSizeConstraint.predicates());

        // Create Validator with predicates
        Validator<String> validator = new Validator<>(
                ".",
                predicatesList,
                new ArrayList<>(),
                new ArrayList<>(),
                null,
                false
        );

        // Act & Assert

        // Test case 1: Byte size equal to minimum
        ConstraintViolations violations = validator.validate("test");
        assertThat(violations.isEmpty()).isTrue();

        // Test case 2: Byte size above minimum
        violations = validator.validate("testing");
        assertThat(violations.isEmpty()).isTrue();

        // Test case 3: Byte size below minimum
        violations = validator.validate("tes");
        assertThat(violations.hasViolations()).isTrue();
        assertThat(violations.getViolations().get(0).value()).isEqualTo("tes");

        // Test case 4: Multi-byte characters equal to minimum
        violations = validator.validate("あい");
        assertThat(violations.isEmpty()).isTrue();

        // Test case 5: Multi-byte characters below minimum
        violations = validator.validate("あ");
        assertThat(violations.hasViolations()).isTrue();
        assertThat(violations.getViolations().get(0).value()).isEqualTo("あ");
    }
