import java.util.Set;
import java.util.stream.Collectors;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

import am.ik.yavi.constraint.charsequence.CodePoints;

class CompositeCodePointsTest {
    @Test
    void excludeNonJapaneseCharacters() {
        CodePoints<String> hiragana = s -> {
            Set<Integer> allowed = new LinkedHashSet<>(Arrays.asList(
                0x3041, // あ
                0x3042  // い
            ));
            return s.codePoints()
                    .filter(cp -> !allowed.contains(cp))
                    .boxed()
                    .collect(Collectors.toSet());
        };

        CodePoints<String> katakana = s -> {
            Set<Integer> allowed = new LinkedHashSet<>(Arrays.asList(
                0x30A1, // ア
                0x30A2  // イ
            ));
            return s.codePoints()
                    .filter(cp -> !allowed.contains(cp))
                    .boxed()
                    .collect(Collectors.toSet());
        };

        // Combine hiragana and katakana exclusions
        CodePoints<String> combined = s -> {
            Set<Integer> excludedHiragana = hiragana.allExcludedCodePoints(s);
            Set<Integer> excludedKatakana = katakana.allExcludedCodePoints(s);
            if (excludedHiragana.isEmpty() || excludedKatakana.isEmpty()) {
                return Collections.emptySet();
            }
            Set<Integer> excluded = new HashSet<>(excludedHiragana);
            excluded.retainAll(excludedKatakana);
            return excluded;
        };

        // Initialize CompositeCodePoints with the combined CodePoints
        CompositeCodePoints<String> codePoints = new CompositeCodePoints<>(combined);

        // Inputs with only Hiragana or Katakana characters
        assertThat(codePoints.allExcludedCodePoints("あ")).isEmpty();
        assertThat(codePoints.allExcludedCodePoints("い")).isEmpty();
        assertThat(codePoints.allExcludedCodePoints("ア")).isEmpty();
        assertThat(codePoints.allExcludedCodePoints("イ")).isEmpty();

        // Inputs with non-Japanese characters
        assertThat(codePoints.allExcludedCodePoints("E")).containsOnly(0x0045);
        assertThat(codePoints.allExcludedCodePoints("EF")).containsExactlyInAnyOrder(0x0045, 0x0046);

        // Mixed inputs with both Japanese and non-Japanese characters
        assertThat(codePoints.allExcludedCodePoints("あE")).containsOnly(0x0045);
        assertThat(codePoints.allExcludedCodePoints("イF")).containsOnly(0x0046);
        assertThat(codePoints.allExcludedCodePoints("あイEF")).containsExactlyInAnyOrder(0x0045, 0x0046);
    }
}

