package am.ik.yavi.fn;

import org.junit.jupiter.api.Test;
import java.util.Arrays;
import java.util.List;
import java.util.NoSuchElementException;
import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertThrows;

class ValidationTest {

    @Test
    void testFailure() {
        List<String> errors = Arrays.asList("Error1", "Error2");
        Validation<String, String> validation = Validation.failure(errors);

        // 1. The validation instance is marked as invalid.
        assertThat(validation.isValid()).isFalse();

        // 2. Accessing the value throws a NoSuchElementException.
        assertThrows(NoSuchElementException.class, validation::value);

        // 3. The errors list contains the specified error messages.
        assertThat(validation.errors()).containsExactly("Error1", "Error2");

        // 4. The map method retains the original errors.
        Validation<String, Integer> mappedValidation = validation.map(String::length);
        assertThat(mappedValidation.isValid()).isFalse();
        assertThat(mappedValidation.errors()).containsExactly("Error1", "Error2");

        // 5. The mapErrors method correctly transforms the error messages.
        Validation<String, String> transformedErrorsValidation = validation.mapErrors(errs -> Arrays.asList("MappedError1", "MappedError2"));
        assertThat(transformedErrorsValidation.errors()).containsExactly("MappedError1", "MappedError2");

        // 6. The flatMap method retains the original errors.
        Validation<String, Integer> flatMappedValidation = validation.flatMap(val -> Validation.success(val.length()));
        assertThat(flatMappedValidation.isValid()).isFalse();
        assertThat(flatMappedValidation.errors()).containsExactly("Error1", "Error2");

        // 7. The validation instance equals another instance with the same errors.
        Validation<String, String> anotherValidation = Validation.failure(errors);
        assertThat(validation).isEqualTo(anotherValidation);

        // 8. The hash code of the validation instance matches another instance with the same errors.
        assertThat(validation.hashCode()).isEqualTo(anotherValidation.hashCode());
    }
}

